void Solver::bump_var(int var, double coeff) {
    // Compute increment and update activity
    double inc = var_inc * coeff;
    activity[var] += inc;

    // Rescale if activity grows beyond a safe threshold
    const double MAX_ACTIVITY = 1e150;
    if (activity[var] > MAX_ACTIVITY) {
        double scale = 1e-150;
        for (int i = 1; i <= vars; ++i) activity[i] *= scale;
        var_inc *= scale;
    }

    // Keep the VSIDS heap consistent
    if (vsids.inHeap(var)) {
        vsids.update(var);
    } else {
        vsids.insert(var);
    }
}
